        {
            if (freq <= tableMaxFreqs[i])
            {
                currentTable = i;
                break;
            }
        }
    }

    float process()
    {
        // Get current table
        const float* table = wavetables[currentTable];

        // Interpolate between samples
        float index = phase * tableLength;
        int i0 = (int)index;
        int i1 = (i0 + 1) % tableLength;
        float frac = index - i0;

        float sample = table[i0] * (1.0f - frac) + table[i1] * frac;

